INSERT INTO "Exercise" (id, name, description, image, muscle_group, difficulty) VALUES
(1, 'Flexiones', 'Ejercicio basico para pecho, hombros y triceps. Colocate en posicion de plancha con las manos a la altura de los hombros y baja el cuerpo hasta que el pecho casi toque el suelo.', 'https://images.unsplash.com/photo-1598971639058-fab3c3109a00?w=800&q=80', ARRAY['chest', 'shoulders', 'triceps'], 1),
(2, 'Dominadas', 'Ejercicio fundamental para espalda y biceps. Cuelgate de una barra con agarre prono y eleva tu cuerpo hasta que la barbilla supere la barra.', 'https://images.unsplash.com/photo-1597452485669-2c7bb5fef90d?w=800&q=80', ARRAY['back', 'biceps'], 2),
(3, 'Sentadilla', 'Sentadilla basica para piernas. Baja las caderas como si fueras a sentarte manteniendo la espalda recta y las rodillas alineadas con los pies.', 'https://images.unsplash.com/photo-1574680096145-d05b474e2155?w=800&q=80', ARRAY['legs', 'glutes'], 1),
(4, 'Fondos', 'Fondos en paralelas para triceps y pecho. Sujetate en barras paralelas y baja el cuerpo flexionando los codos hasta formar un angulo de 90 grados.', 'https://images.unsplash.com/photo-1598266663439-2056e6900339?w=800&q=80', ARRAY['triceps', 'chest', 'shoulders'], 2),
(5, 'Plancha', 'Plancha isometrica para core. Manten el cuerpo recto apoyado sobre antebrazos y puntas de los pies, activando el abdomen.', 'https://images.unsplash.com/photo-1566241142559-40e1dab266c6?w=800&q=80', ARRAY['core', 'shoulders'], 1),
(6, 'Muscle Up', 'Ejercicio avanzado que combina dominada y fondo. Realiza una dominada explosiva y transiciona sobre la barra para completar un fondo.', 'https://images.unsplash.com/photo-1526506118085-60ce8714f8c5?w=800&q=80', ARRAY['back', 'chest', 'triceps', 'shoulders'], 5),
(7, 'Sentadilla Pistola', 'Sentadilla a una pierna. Baja completamente sobre una pierna mientras mantienes la otra extendida al frente.', 'https://images.unsplash.com/photo-1434682881908-b43d0467b798?w=800&q=80', ARRAY['legs', 'glutes', 'core'], 4),
(8, 'Flexion en Pino', 'Flexiones en posicion de pino. Realiza una flexion mientras estas en posicion invertida contra una pared o en equilibrio libre.', 'https://images.unsplash.com/photo-1544367567-0f2fcb009e0b?w=800&q=80', ARRAY['shoulders', 'triceps', 'core'], 5),
(9, 'L-Sit', 'Posicion isometrica de L. Sientate con las piernas extendidas y eleva todo el cuerpo del suelo usando solo las manos.', 'https://images.unsplash.com/photo-1599058917765-a780eda07a3e?w=800&q=80', ARRAY['core', 'triceps', 'shoulders'], 3),
(10, 'Remo Australiano', 'Dominada horizontal para principiantes. Cuelgate de una barra baja con los pies en el suelo y tira del pecho hacia la barra.', 'https://images.unsplash.com/photo-1571019614242-c5c5dee9f50b?w=800&q=80', ARRAY['back', 'biceps'], 1),
(11, 'Flexion Diamante', 'Flexiones con manos juntas formando un diamante. Mayor enfasis en triceps que las flexiones regulares.', 'https://images.unsplash.com/photo-1598971457999-ca4ef48a9a71?w=800&q=80', ARRAY['triceps', 'chest'], 2),
(12, 'Dominadas Supinas', 'Dominada con agarre supino. Similar a la dominada pero con las palmas mirando hacia ti, mayor enfasis en biceps.', 'https://images.unsplash.com/photo-1605296867304-46d5465a13f1?w=800&q=80', ARRAY['biceps', 'back'], 2),
(13, 'Burpee', 'Ejercicio de cuerpo completo. Combina una sentadilla, plancha, flexion y salto en un movimiento continuo.', 'https://images.unsplash.com/photo-1434608519344-49d77a699e1d?w=800&q=80', ARRAY['legs', 'chest', 'core', 'shoulders'], 2),
(14, 'Front Lever', 'Posicion horizontal colgado de la barra. Manten el cuerpo completamente horizontal mirando hacia arriba.', 'https://images.unsplash.com/photo-1517836357463-d25dfeac3438?w=800&q=80', ARRAY['back', 'core', 'shoulders'], 5),
(15, 'Back Lever', 'Posicion horizontal invertida en la barra. Manten el cuerpo horizontal mirando hacia el suelo.', 'https://images.unsplash.com/photo-1534438327276-14e5300c3a48?w=800&q=80', ARRAY['shoulders', 'back', 'core'], 4),
(16, 'Bandera Humana', 'Bandera humana. Manten el cuerpo horizontal agarrado a un poste vertical.', 'https://images.unsplash.com/photo-1583454110551-21f2fa2afe61?w=800&q=80', ARRAY['core', 'shoulders', 'back'], 5),
(17, 'Flexion Arquero', 'Flexion arquero. Una mano cerca del cuerpo mientras la otra se extiende lateralmente.', 'https://images.unsplash.com/photo-1616803689943-5601631c7fec?w=800&q=80', ARRAY['chest', 'triceps', 'shoulders'], 3),
(18, 'Tuck Planche', 'Planche con rodillas recogidas. Equilibrio sobre las manos con el cuerpo elevado y rodillas al pecho.', 'https://images.unsplash.com/photo-1518611012118-696072aa579a?w=800&q=80', ARRAY['shoulders', 'chest', 'core'], 4),
(19, 'Dragon Flag', 'Ejercicio avanzado de core. Acostado boca arriba, eleva las piernas y caderas manteniendo solo los hombros en contacto con el banco.', 'https://images.unsplash.com/photo-1571019613454-1cb2f99b2d8b?w=800&q=80', ARRAY['core'], 4),
(20, 'Elevacion de Piernas Colgado', 'Elevacion de piernas colgado. Cuelgate de una barra y eleva las piernas rectas hasta formar un angulo de 90 grados.', 'https://images.unsplash.com/photo-1597347316205-36f6c451902a?w=800&q=80', ARRAY['core'], 2),
(21, 'Flexion en Pared', 'Flexion contra la pared. El ejercicio mas basico de la progresion de flexiones, ideal para principiantes absolutos.', 'https://images.unsplash.com/photo-1571019614242-c5c5dee9f50b?w=800&q=80', ARRAY['chest', 'shoulders', 'triceps'], 0),
(22, 'Flexion Inclinada', 'Flexion inclinada con manos en superficie elevada. Reduce la carga comparado con la flexion estandar.', 'https://images.unsplash.com/photo-1598971639058-fab3c3109a00?w=800&q=80', ARRAY['chest', 'shoulders', 'triceps'], 0),
(23, 'Flexion de Rodillas', 'Flexion con rodillas apoyadas. Version modificada que reduce la carga corporal en aproximadamente un 50%.', 'https://images.unsplash.com/photo-1598971639058-fab3c3109a00?w=800&q=80', ARRAY['chest', 'shoulders', 'triceps'], 1),
(24, 'Flexion Abierta', 'Flexion con manos mas separadas que el ancho de hombros. Mayor enfasis en el pecho.', 'https://images.unsplash.com/photo-1598971639058-fab3c3109a00?w=800&q=80', ARRAY['chest', 'shoulders'], 1),
(25, 'Flexion a Una Mano', 'Flexion a una mano. Ejercicio avanzado que requiere gran fuerza y estabilidad del core.', 'https://images.unsplash.com/photo-1598971639058-fab3c3109a00?w=800&q=80', ARRAY['chest', 'shoulders', 'triceps', 'core'], 5),
(26, 'Dominada Escapular', 'Activacion escapular colgado de la barra. Primer paso para construir fuerza de tiron.', 'https://images.unsplash.com/photo-1597452485669-2c7bb5fef90d?w=800&q=80', ARRAY['back', 'shoulders'], 0),
(27, 'Dominada Negativa', 'Dominada negativa. Salta arriba y baja lentamente controlando el movimiento.', 'https://images.unsplash.com/photo-1597452485669-2c7bb5fef90d?w=800&q=80', ARRAY['back', 'biceps'], 1),
(28, 'Dominada con Banda', 'Dominada asistida con banda elastica. La banda reduce el peso corporal que debes levantar.', 'https://images.unsplash.com/photo-1597452485669-2c7bb5fef90d?w=800&q=80', ARRAY['back', 'biceps'], 1),
(29, 'Dominada con Peso', 'Dominada con peso adicional. Progresion avanzada para aumentar la fuerza de tiron.', 'https://images.unsplash.com/photo-1597452485669-2c7bb5fef90d?w=800&q=80', ARRAY['back', 'biceps'], 3),
(30, 'Sentadilla Asistida', 'Sentadilla asistida sujetandose de algo. Ideal para aprender la tecnica correcta.', 'https://images.unsplash.com/photo-1574680096145-d05b474e2155?w=800&q=80', ARRAY['legs', 'glutes'], 0),
(31, 'Sentadilla en Caja', 'Sentadilla a una caja o banco. Ayuda a controlar la profundidad y la tecnica.', 'https://images.unsplash.com/photo-1574680096145-d05b474e2155?w=800&q=80', ARRAY['legs', 'glutes'], 0),
(32, 'Sentadilla Bulgara', 'Sentadilla bulgara con pie trasero elevado. Trabaja cada pierna de forma unilateral.', 'https://images.unsplash.com/photo-1574680096145-d05b474e2155?w=800&q=80', ARRAY['legs', 'glutes', 'core'], 2),
(33, 'Sentadilla Camaron', 'Sentadilla camaron. Variante avanzada de sentadilla a una pierna con la pierna trasera sujeta.', 'https://images.unsplash.com/photo-1574680096145-d05b474e2155?w=800&q=80', ARRAY['legs', 'glutes', 'core'], 4),
(34, 'Fondos en Banco', 'Fondos en banco. Version mas facil de los fondos usando un banco o silla.', 'https://images.unsplash.com/photo-1598266663439-2056e6900339?w=800&q=80', ARRAY['triceps', 'chest'], 1),
(35, 'Fondos Asistidos', 'Fondos asistidos con banda o maquina. Reduce la carga corporal para construir fuerza.', 'https://images.unsplash.com/photo-1598266663439-2056e6900339?w=800&q=80', ARRAY['triceps', 'chest', 'shoulders'], 1),
(36, 'Fondos en Anillas', 'Fondos en anillas. Requiere mayor estabilidad y fuerza que los fondos en paralelas.', 'https://images.unsplash.com/photo-1598266663439-2056e6900339?w=800&q=80', ARRAY['triceps', 'chest', 'shoulders', 'core'], 3),
(37, 'Fondos con Peso', 'Fondos con peso adicional. Progresion para aumentar la fuerza de empuje.', 'https://images.unsplash.com/photo-1598266663439-2056e6900339?w=800&q=80', ARRAY['triceps', 'chest', 'shoulders'], 3),
(38, 'Plancha Inclinada', 'Plancha inclinada con manos en superficie elevada. Version mas facil de la plancha.', 'https://images.unsplash.com/photo-1566241142559-40e1dab266c6?w=800&q=80', ARRAY['core'], 0),
(39, 'Plancha Lateral', 'Plancha lateral. Trabaja los oblicuos y la estabilidad lateral del core.', 'https://images.unsplash.com/photo-1566241142559-40e1dab266c6?w=800&q=80', ARRAY['core', 'shoulders'], 2),
(40, 'Plancha con Elevacion de Pierna', 'Plancha con elevacion de pierna. Aumenta la demanda de estabilidad del core.', 'https://images.unsplash.com/photo-1566241142559-40e1dab266c6?w=800&q=80', ARRAY['core', 'shoulders', 'glutes'], 2),
(41, 'Dominada Alta', 'Dominada alta llevando la barra al pecho o mas abajo. Prepara para el muscle up.', 'https://images.unsplash.com/photo-1526506118085-60ce8714f8c5?w=800&q=80', ARRAY['back', 'biceps', 'shoulders'], 3),
(42, 'Dominada Explosiva', 'Dominada explosiva con fase de vuelo. Desarrolla la potencia necesaria para el muscle up.', 'https://images.unsplash.com/photo-1526506118085-60ce8714f8c5?w=800&q=80', ARRAY['back', 'biceps', 'shoulders'], 4),
(43, 'L-Sit Recogido', 'L-Sit con rodillas recogidas. Primera progresion hacia el L-Sit completo.', 'https://images.unsplash.com/photo-1599058917765-a780eda07a3e?w=800&q=80', ARRAY['core', 'triceps'], 2),
(44, 'V-Sit', 'Posicion en V con piernas elevadas por encima de la horizontal. Progresion avanzada del L-Sit.', 'https://images.unsplash.com/photo-1599058917765-a780eda07a3e?w=800&q=80', ARRAY['core', 'triceps', 'shoulders'], 4),
(45, 'Flexion Pike', 'Flexion en pike. Simula el movimiento de la flexion en pino con menos carga.', 'https://images.unsplash.com/photo-1544367567-0f2fcb009e0b?w=800&q=80', ARRAY['shoulders', 'triceps'], 2),
(46, 'Flexion Pike Elevada', 'Flexion pike con pies elevados. Mayor carga en los hombros que el pike normal.', 'https://images.unsplash.com/photo-1544367567-0f2fcb009e0b?w=800&q=80', ARRAY['shoulders', 'triceps', 'core'], 3),
(47, 'Flexion en Pino contra Pared', 'Flexion en pino contra la pared. Version asistida de la flexion en pino libre.', 'https://images.unsplash.com/photo-1544367567-0f2fcb009e0b?w=800&q=80', ARRAY['shoulders', 'triceps', 'core'], 4),
(48, 'Dead Bug', 'Ejercicio de core tumbado boca arriba moviendo brazos y piernas de forma alterna.', 'https://images.unsplash.com/photo-1566241142559-40e1dab266c6?w=800&q=80', ARRAY['core'], 1),
(49, 'Hollow Body Hold', 'Posicion hollow con espalda baja pegada al suelo. Fundamental para gimnasia.', 'https://images.unsplash.com/photo-1566241142559-40e1dab266c6?w=800&q=80', ARRAY['core'], 2),
(50, 'Elevacion de Rodillas', 'Elevacion de rodillas colgado. Version mas facil de la elevacion de piernas.', 'https://images.unsplash.com/photo-1597347316205-36f6c451902a?w=800&q=80', ARRAY['core'], 1),
(51, 'Toes to Bar', 'Llevar los pies a la barra colgado. Progresion avanzada de la elevacion de piernas.', 'https://images.unsplash.com/photo-1597347316205-36f6c451902a?w=800&q=80', ARRAY['core', 'back'], 3),
(52, 'Tuck Front Lever', 'Front lever con rodillas recogidas al pecho. Primera progresion del front lever.', 'https://images.unsplash.com/photo-1517836357463-d25dfeac3438?w=800&q=80', ARRAY['back', 'core'], 3),
(53, 'Advanced Tuck Front Lever', 'Front lever con rodillas ligeramente extendidas. Progresion intermedia.', 'https://images.unsplash.com/photo-1517836357463-d25dfeac3438?w=800&q=80', ARRAY['back', 'core', 'shoulders'], 4),
(54, 'Straddle Front Lever', 'Front lever con piernas abiertas. Progresion avanzada hacia el full front lever.', 'https://images.unsplash.com/photo-1517836357463-d25dfeac3438?w=800&q=80', ARRAY['back', 'core', 'shoulders'], 5),
(55, 'Tuck Back Lever', 'Back lever con rodillas recogidas. Primera progresion del back lever.', 'https://images.unsplash.com/photo-1534438327276-14e5300c3a48?w=800&q=80', ARRAY['shoulders', 'back', 'core'], 2),
(56, 'Straddle Back Lever', 'Back lever con piernas abiertas. Progresion hacia el full back lever.', 'https://images.unsplash.com/photo-1534438327276-14e5300c3a48?w=800&q=80', ARRAY['shoulders', 'back', 'core'], 3),
(57, 'Planche Lean', 'Inclinacion de planche en posicion de flexion. Desarrolla fuerza de empuje.', 'https://images.unsplash.com/photo-1518611012118-696072aa579a?w=800&q=80', ARRAY['shoulders', 'chest', 'core'], 2),
(58, 'Straddle Planche', 'Planche con piernas abiertas. Progresion avanzada hacia el full planche.', 'https://images.unsplash.com/photo-1518611012118-696072aa579a?w=800&q=80', ARRAY['shoulders', 'chest', 'core'], 5),
(59, 'Full Planche', 'Planche completa con piernas juntas y extendidas. Uno de los ejercicios mas dificiles.', 'https://images.unsplash.com/photo-1518611012118-696072aa579a?w=800&q=80', ARRAY['shoulders', 'chest', 'core'], 5)
